  const dk=nearDeck(b.x,b.y,30);if(dk){clearFishState();S.aboard=null;P().aboard=null;PlayerPed.x=dk[0];PlayerPed.y=dk[1];PlayerPed.pose='idle';b.mode='return';b.legs=legsHome(b);if(b.owned){if(HOOK.left)HOOK.left(b,'deck')}else closeRental('deck');return true}
  return toast(inBasin(b.x,b.y)?'אי אפשר לרדת כאן — מתקרבים למזח או למעגן '+be.n:'אי אפשר לרדת מהסירה בים — חוזרים למרינה')}

functions.FISH3.init:
function init(){const p=P();if(S.lastP===p)return;S.lastP=p;S.f=null;if(HOOK.sync)try{HOOK.sync(p)}catch(e){er('sync',e)}
  for(const b of BOATS){const st=p.boats[b.id];b.trail=[];b.u=0;b.vl=0;b.r=0;b.hitT=0;b.legs=[];
   if(st&&Number.isFinite(st.x)&&Number.isFinite(st.y)){b.x=st.x;b.y=st.y;b.h=st.h||0;b.mode=st.mode==='moored'?'moored':'return'}else{b.x=b.be.cx;b.y=b.be.cy;b.h=b.be.h;b.mode='moored'}}
  S.aboard=null;const a=p.aboard&&boatById(p.aboard);
  if(a&&PlayerProfile.mode==='walk'&&Math.hypot(PlayerPed.x-a.x,PlayerPed.y-a.y)<60){S.aboard=a.id;a.mode='player';placePed(a)}else{p.aboard=null;for(const b of BOATS)if(b.mode==='return')b.legs=legsHome(b)}if(HOOK.after)try{HOOK.after(p)}catch(e){er('after',e)}}

functions.FISH3.stepAll:
function stepAll(dt){try{init();if(S.aboard){const b=boatById(S.aboard);if(PlayerProfile.mode!=='walk'||State.taxiRide||State.ferryRide||Math.hypot(PlayerPed.x-S.pedX,PlayerPed.y-S.pedY)>40){leaveBoat(b,'away');if(!b.owned)try{g77MsgIn('pl-club','השארת את "'+b.name+'" — אני מחזיר אותה למעגן.')}catch(e){}}}
   for(const b of BOATS){if(b.id===S.aboard&&(b.mode==='player'||b.mode==='moor'||b.mode==='auto'))continue;   /* D‑569: הסירה שהשחקן עליה מתקדמת ב-stepAboard בלבד — קודם הטייס (עגינה, הדגמה) רץ פעמיים בכל פריים, והסירה שטה במהירות כפולה */
   if(b.mode==='return'||b.mode==='moor'||b.mode==='auto'||b.mode==='yard')autopilot(b,dt);if(b.mode!=='moored'||!b.saved){save(b);b.saved=b.mode==='moored'}}
   if(HOOK.step)HOOK.step(dt);rentalTick()}catch(e){er('step',e)}}
